async function flightUIFixture({date='2027-02-21',destination='CDG',partnerPrestige=false,partnerNoSeat=false}={}){
 const {unpackDocument}=await import('../dist/model.js'),raw=await unpackDocument(ke),original=Object.values(raw.records)[0],month=date.slice(0,7),count=28;const current={carrier:'KE',origin:'ICN',destination,month,sourceUpdatedAt:original.current.sourceUpdatedAt,collectedAt:original.current.collectedAt,flightDetailPolicyVersion:1,dates:Array.from({length:count},(_,i)=>({date:month+'-'+String(i+1).padStart(2,'0'),status:'UNKNOWN',...Object.fromEntries(TEST_FIELDS.map(f=>[f,false])),flightDetailStatus:'UNKNOWN',flights:[]}))};
 const d=current.dates.find(d=>d.date===date),own={number:'KE901',departureTime:'12:05',...Object.fromEntries(TEST_FIELDS.map(f=>[f,['economyAward','prestigeAward','prestigeUpgrade'].includes(f)]))},partner={number:'KE5901',departureTime:'13:20',...Object.fromEntries(TEST_FIELDS.map(f=>[f,!partnerNoSeat&&(f==='economyAward'||partnerPrestige&&f==='prestigeAward')]))};if(partnerNoSeat)partner.noSeat=true;Object.assign(d,{status:'OBSERVED',flightDetailStatus:'CAPTURED',flightDetailDate:date,flightDetailObservedAt:'2026-10-31T14:00:00Z',flights:[own,partner]},Object.fromEntries(TEST_FIELDS.map(f=>[f,own[f]||partner[f]])));raw.records['ICN-'+destination+'-'+month]={current,previous:null,success:original.success};
 const week=JSON.parse(await readFile(new URL('evidence138/schema2-week-captured-dom.json',import.meta.url)));week.observedAt='2026-10-31T14:00:00Z';week.destination=destination;return {raw,policy:{schema:1,weeks:[week]}};
}
function selectFlightMonth(p,destination='CDG'){choose(p,'destination',destination);choose(p,'month','2027-02');}
function uiTimetable({operatorCode='KE',operatorName='대한항공',serviceKind='DIRECT',coverage='WEEKDAYS',start='2027-02-15',end='2027-02-21',confirmedDates=[],weekdays=[0,2,3,4,5,6],noFlightWeekdays=[1]}={}){return {schema:1,sourceKind:'USER_SUPPLIED_TIMETABLE',sourceAsOf:'2026-11-02',validFrom:'2026-11-02',validThrough:'2027-11-01',completeOperators:false,records:[{origin:'ICN',destination:'CDG',operatorCode,operatorName,serviceKind,start,end,coverage,confirmedDates,weekdays,noFlightWeekdays,note:'시험 입력',sourceUrls:['https://www.koreanair.com/flight-status'],sourceRows:[{sheet:'시험',row:1}]}]};}
