test('Asiana full-period columns count business award and upgrade independently in both directions',async()=>{
 const p=await page();try{await p.ready();p.d.getElementById('tab-oz').click();await waitFor(()=>p.d.getElementById('load-status').textContent.includes('104개'));
 const {unpackDocument}=await import('../dist/model.js'),raw=await unpackDocument(oz),start=p.d.getElementById('start').value,end=p.d.getElementById('end').value;
 for(const card of p.d.querySelectorAll('.route-card')){assert.equal(card.querySelectorAll('[data-total-field]').length,2);assert.equal(card.querySelector('[data-total-field="firstCombined"]'),null);
  for(const field of ['prestigeAward','prestigeUpgrade'])for(const direction of ['out','back']){const observed=Object.values(raw.records).filter(x=>direction==='out'?x.current.origin==='ICN'&&x.current.destination===card.dataset.code:x.current.origin===card.dataset.code&&x.current.destination==='ICN').flatMap(x=>x.current.dates).filter(d=>d.status==='OBSERVED'&&d.date>=start&&d.date<=end);assert.equal(card.querySelector(`[data-total-field="${field}"] [data-direction="${direction}"]`).textContent,observed.length?observed.filter(d=>d[field]).length+'일':'미확인');}
 }
 }finally{p.close();}
});

test('refresh failure retains previously verified route calendars instead of clearing them',async()=>{
 const p=await page();try{await p.ready();const count=p.d.querySelectorAll('.route-card').length;assert.ok(count>0);p.denyKorean();p.d.getElementById('refresh').click();await waitFor(()=>!p.d.getElementById('refresh').disabled);assert.equal(p.d.querySelectorAll('.route-card').length,count);assert.equal(p.d.getElementById('notice').hidden,false);assert.ok(p.d.querySelectorAll('#calendar-grid button').length>0);}finally{p.close();}
});


async function regionalReopenFixture(){
 const {unpackDocument}=await import('../dist/model.js'),body=await unpackDocument(ke),original=Object.values(body.records)[0];
 for(const [destination,month] of [['BKK','2026-12'],['BKK','2027-01'],['JFK','2027-01']]){const count=new Date(Date.UTC(+month.slice(0,4),+month.slice(5,7),0)).getUTCDate(),current={carrier:'KE',origin:'ICN',destination,month,sourceUpdatedAt:original.current.sourceUpdatedAt,collectedAt:original.current.collectedAt,dates:Array.from({length:count},(_,i)=>({date:month+'-'+String(i+1).padStart(2,'0'),status:'OBSERVED',...Object.fromEntries(TEST_FIELDS.map(f=>[f,f==='prestigeUpgrade']))}))};body.records['ICN-'+destination+'-'+month]={current,previous:null,success:original.success};}
 return body;
}
test('KE opens Europe and USA through the359-day booking horizon and retains a selected future month across airline tabs',async()=>{const p=await page();try{await p.ready();const {addDays}=await import('../dist/model.js'),start=p.d.getElementById('start').value,end=p.d.getElementById('end');assert.equal(end.value,addDays(start,359));assert.equal(end.max,addDays(start,359));assert.equal(p.d.getElementById('start').max,addDays(start,359));choose(p,'destination','FCO');choose(p,'month','2027-01');assert.equal(p.d.getElementById('month').value,'2027-01');p.d.getElementById('tab-oz').click();await waitFor(()=>p.d.getElementById('load-status').textContent.includes('104개'));assert.equal(end.value,addDays(start,359));p.d.getElementById('tab-ke').click();await waitFor(()=>p.d.getElementById('load-status').textContent.includes('72개'));choose(p,'destination','FCO');assert.equal(end.value,addDays(start,359));assert.equal(p.d.getElementById('month').value,'2027-01');assert.ok(p.d.querySelector('[data-date="2027-01-01"]'));}finally{p.close();}});
test('European and USA calendars reopen later dates while another KE region remains capped even after a forged future month selection',async()=>{const p=await page({keData:await regionalReopenFixture()});try{await p.ready();choose(p,'destination','FCO');choose(p,'month','2026-12');assert.equal(p.d.querySelector('[data-date="2026-12-18"]').disabled,false);assert.equal(p.d.querySelectorAll('#calendar-grid button').length,31);assert.equal(p.d.getElementById('next-month').disabled,false);choose(p,'destination','JFK');choose(p,'month','2027-01');assert.equal(p.d.querySelector('[data-date="2027-01-18"]').disabled,false);assert.equal(p.d.querySelector('#calendar-counts [data-field="prestigeUpgrade"] strong').textContent,'31일');choose(p,'destination','BKK');choose(p,'month','2026-12');assert.equal(p.d.querySelector('[data-date="2026-12-17"]').disabled,false);assert.equal(p.d.querySelector('[data-date="2026-12-18"]'),null);assert.equal(p.d.querySelectorAll('#calendar-grid button').length,17);assert.equal(p.d.getElementById('next-month').disabled,true);choose(p,'month','2027-01');assert.equal(p.d.getElementById('month').value,'2026-12');assert.equal(p.d.querySelector('[data-date="2027-01-01"]'),null);assert.ok([...p.d.querySelectorAll('#calendar-grid button')].every(e=>e.dataset.date<='2026-12-17'));choose(p,'destination','FCO');assert.equal(p.d.querySelectorAll('#calendar-grid button').length,31);}finally{p.close();}});
test('reopened KE form accepts December18 and rejects dates after359 days while Asiana keeps the same horizon',async()=>{const p=await page();try{await p.ready();const {addDays}=await import('../dist/model.js'),start=p.d.getElementById('start').value,end=p.d.getElementById('end'),calls=p.calls.length;choose(p,'destination','FCO');end.value='2026-12-18';p.d.getElementById('search-form').dispatchEvent(new p.w.Event('submit',{bubbles:true,cancelable:true}));assert.equal(p.d.getElementById('form-error').hidden,true);const totals=p.d.getElementById('route-list').textContent;end.value=addDays(start,360);p.d.getElementById('search-form').dispatchEvent(new p.w.Event('submit',{bubbles:true,cancelable:true}));assert.equal(p.d.getElementById('form-error').hidden,false);assert.match(p.d.getElementById('form-error').textContent,/359/);assert.equal(p.d.getElementById('route-list').textContent,totals);assert.equal(p.calls.length,calls);p.d.getElementById('tab-oz').click();await waitFor(()=>p.d.getElementById('load-status').textContent.includes('104개'));assert.equal(end.value,addDays(start,359));end.value=addDays(start,360);p.d.getElementById('search-form').dispatchEvent(new p.w.Event('submit',{bubbles:true,cancelable:true}));assert.equal(p.d.getElementById('form-error').hidden,false);assert.match(p.d.getElementById('form-error').textContent,/359/);}finally{p.close();}});
test('KE homepage notices identify Europe and USA reopening, remaining regional cutoff and codeshare exclusion without removed old messages',async()=>{const p=await page();try{await p.ready();const notice=p.d.getElementById('ke-range-notice');assert.equal(notice.hidden,false);assert.equal(notice.getAttribute('role'),'note');assert.match(notice.textContent,/유럽.*미국/);assert.match(notice.textContent,/12월 18일 이후/);assert.match(notice.textContent,/그 외|나머지/);assert.match(notice.textContent,/2026년 12월 17일까지/);assert.doesNotMatch(p.d.body.textContent,/대한항공 직접 운항·공동운항편을 함께 표시합니다|직접 운항편 수·금·일 출발 기준|좌석 표식 오류로 잠시 수정 중/);assert.match(p.d.getElementById('ke-nonoperation-notice').textContent,/공동운항편은 제외됩니다/);assert.equal(notice.querySelector('dialog'),null);}finally{p.close();}});


test('both airline screens omit excluded regions and cached destination routes while keeping the explicit removal notice',async()=>{
 const {unpackDocument}=await import('../dist/model.js'),keData=await unpackDocument(ke),ozData=await unpackDocument(oz);
 for(const [carrier,body] of [['KE',keData],['OZ',ozData]]){const template=Object.values(body.records)[0];for(const [origin,destination] of [['ICN','NRT'],['NRT','ICN'],['ICN','CAN'],['ICN','GMP'],['GMP','ICN']]){const value=structuredClone(template);Object.assign(value.current,{carrier,origin,destination});body.records[`${origin}-${destination}-${value.current.month}`]=value;}}
 const p=await page({keData,ozData});try{await p.ready();for(const carrier of ['KE','OZ']){if(carrier==='OZ'){p.d.getElementById('tab-oz').click();await waitFor(()=>p.d.body.dataset.carrier==='OZ'&&!p.d.getElementById('refresh').disabled);}
  const regionValues=[...p.d.getElementById('region').options].map(option=>option.value),countryValues=[...p.d.getElementById('country').options].map(option=>option.value),airportValues=[...p.d.getElementById('destination').options].map(option=>option.value);
  assert.ok(!regionValues.includes('동북아시아'));assert.ok(!regionValues.includes('대한민국'));for(const code of ['JP','CN','KR'])assert.ok(!countryValues.includes(code));for(const code of ['NRT','CAN','GMP','CJU'])assert.ok(!airportValues.includes(code));assert.ok(airportValues.includes('CDG'));assert.ok(airportValues.includes('BKK'));
  const routes=[...p.d.querySelectorAll('.route-card')].map(card=>card.dataset.code);assert.ok(!routes.includes('NRT'));assert.ok(!routes.includes('CAN'));assert.ok(!routes.includes('GMP'));assert.ok(routes.includes('LHR'));
  const notice=p.d.getElementById('excluded-region-notice');assert.ok(notice);assert.equal(notice.hidden,false);assert.match(notice.textContent,/대한항공·아시아나/);assert.match(notice.textContent,/동북아·한국/);assert.match(notice.textContent,/조회 대상에서 제외/);
 }
 assert.ok(p.calls.every(call=>!call.url.endsWith('/east_asia.json')&&!call.url.endsWith('/korea.json')));
 }finally{p.close();}
});
